<?php
 namespace QQWorld\Catalog\Test\Unit\Controller\Adminhtml\Product\Initialization\Helper; use \QQWorld\Catalog\Controller\Adminhtml\Product\Initialization\Helper\HandlerFactory; class HandlerFactoryTest extends \PHPUnit\Framework\TestCase { protected $_model; protected $_objectManagerMock; protected function setUp() { $this->_objectManagerMock = $this->createMock(\QQWorld\Framework\ObjectManagerInterface::class); $this->_model = new HandlerFactory($this->_objectManagerMock); } public function testCreateWithInvalidType() { $this->expectException( '\InvalidArgumentException', \QQWorld\Framework\DataObject::class . ' does not implement ' . \QQWorld\Catalog\Controller\Adminhtml\Product\Initialization\Helper\HandlerInterface::class ); $this->_objectManagerMock->expects($this->never())->method('create'); $this->_model->create(\QQWorld\Framework\DataObject::class); } public function testCreateWithValidType() { $this->_objectManagerMock->expects( $this->once() )->method( 'create' )->with( \QQWorld\Catalog\Controller\Adminhtml\Product\Initialization\Helper\Plugin\Handler\Composite::class )->will( $this->returnValue('object') ); $this->assertEquals( 'object', $this->_model->create( \QQWorld\Catalog\Controller\Adminhtml\Product\Initialization\Helper\Plugin\Handler\Composite::class ) ); } } 